"""Six purpose-built massive constructs, directly painted at native64."""
from arcane_core import Pixels,palette,PAL,SWING
SPECIES={
'golem':'이끼가 덮인 청록빛 바위 거인이 넓은 등과 층층이 쌓인 주먹, 가슴 보석을 갖는다.',
'golem-stone':'회색 각진 거석과 깊은 균열, 불균형한 넓은 어깨와 돌 코를 가진 육중한 골렘이다.',
'golem-clay':'붉은 점토 항아리의 두꺼운 굴곡과 깨진 테두리, 도기 손잡이 팔과 원형 문양이 보인다.',
'golem-iron':'어두운 강철 판금 거인이 커다란 어깨, 노란 눈과 붉은 화로, 리벳이 박힌 주먹을 갖는다.',
'golem-crystal':'보라색 결정 골렘의 넓은 흉곽과 큰 비대칭 어깨, 긴 손가락에 자수정 면이 겹친다.',
'spirit-earth':'이끼와 휘어진 뿌리로 연결된 서로 다른 크기의 암석과 돌 얼굴이 따로 떠 있다.'}
RAMPS={
'golem':('284942','42695b','6c9377','9cb294','d0d6af'),
'golem-stone':('333f49','536570','7f9297','acbab3','d5d8bd'),
'golem-clay':('633e42','975b51','c88969','e9b78b','f0d4a5'),
'golem-iron':('25343f','3f5564','657f8c','9eafb0','d3d6c2'),
'golem-crystal':('39334f','5d4976','9073a9','bba1cc','e1d0df'),
'spirit-earth':('41473c','677054','979d75','c0c69c','dddcb7')}
def block(p,x,y,w,h,seed=0,crystal=False):
    pts=[(x-w,y-h+3),(x-w+4,y-h),(x+w-3,y-h+1),(x+w,y-h+5),(x+w-1,y+h-2),(x+w-5,y+h),(x-w+2,y+h-1),(x-w,y+2)]
    if crystal:pts=[(x-w,y+1),(x-w+4,y-h+2),(x+1,y-h-2),(x+w,y-h+5),(x+w-1,y+h-1),(x+1,y+h+2),(x-w+3,y+h-1)]
    p.poly(pts,'s',True);p.poly([(x-w+2,y-h+4),(x-2,y-h+2),(x+2,y),(x-1,y+h-2),(x-w+3,y+h-3)],'m');p.poly([(x-1,y-h+2),(x+w-3,y-h+3),(x+w-2,y-2),(x+3,y)],'g');p.line([(x-w+4,y-h+2),(x-1,y-h+1)],'h')
    p.poly([(x+3,y+1),(x+w-2,y-1),(x+w-3,y+h-2),(x+1,y+h-1)],'d');p.line([(x+4,y),(x+2,y+3),(x+3,y+min(h-2,5))],'s')
    if seed%2:p.line([(x-4,y-3),(x-1,y-1),(x-3,y+2),(x-1,y+min(h-2,4))],'d')
    else:p.cluster(x-w+4,y,['gmm','..ms','.sd.'])

def fists(p,kind,cy):
    s=SWING[p.pose];lx=10-s/3;ly=cy+9-s/3;rx=52+s/4;ry=cy+6-s/2
    if p.pose=='windup':rx=45;ry=17;lx=11;ly=35
    elif p.pose=='attack':rx=52;ry=48;lx=22;ly=47
    elif p.pose=='hit':rx=48;ry=47;lx=9;ly=45
    lx=max(11,min(16,lx)) if p.pose!='attack' else lx;rx=min(53,rx)
    p.joint([(19,cy-6),(15,cy+3),(lx,ly)],8,'s','m','d');p.joint([(43,cy-7),(49,cy),(rx,ry)],9,'s','m','d')
    block(p,lx,ly,6,8,1,kind=='crystal');block(p,rx,ry,7,8,0,kind=='crystal')
    for x,y in ((lx,ly),(rx,ry)):p.line([(x-4,y+4),(x+3,y+3)],'d');p.line([(x-3,y-4),(x+2,y-4)],'g');p.cluster(x-4,y+1,['mm','ds'])
    return lx,ly,rx,ry

def draw(slug,pose,cell):
    p=Pixels(pose,cell,palette(RAMPS[slug]))
    if slug=='golem-clay':return urn(p)
    if slug=='golem-iron':return iron(p)
    if slug=='golem-crystal':return crystal(p)
    if slug=='spirit-earth':return earth(p)
    stone=slug=='golem-stone'
    if pose=='dead':
        for j,(x,y,w,h) in enumerate([(10,55,7,5),(25,53,8,7),(41,55,9,5),(53,56,6,4)]):block(p,x,y,w,h,j)
        p.line([(36,53),(43,54)],'o',2);p.poly([(18,51),(22,48),(27,50),(25,53),(20,54)],'F' if not stone else 'm');p.cluster(21,50,['ug','Cm']);return p.im
    # Heavy staggered stone shins and flat feet.
    for part,x in [('leftleg',20),('rightleg',42)]:
        p.part=part;block(p,x,49,7,7,1);p.poly([(x-7,55),(x+5,55),(x+9,58),(x+9,60),(x-8,60),(x-9,58)],'s',True);p.poly([(x-6,56),(x+4,56),(x+6,58),(x-6,58)],'m');p.line([(x-4,56),(x+3,56)],'g');p.cluster(x+3,58,['dsd','mm.'])
    p.part='body'
    if stone:
        p.poly([(17,25),(24,22),(38,23),(47,30),(48,40),(43,48),(34,52),(20,50),(14,43),(13,32)],'s',True);p.poly([(18,28),(25,25),(35,26),(41,31),(38,37),(28,39),(18,35)],'m');p.poly([(22,27),(26,24),(34,26),(36,29),(28,30)],'g');p.poly([(16,37),(27,40),(39,38),(44,42),(38,49),(25,48),(18,44)],'d');p.poly([(19,37),(25,38),(27,42),(24,46),(19,43)],'m');p.poly([(30,40),(38,40),(41,43),(35,46),(29,46)],'m');p.line([(30,25),(28,31),(31,35),(29,41),(31,47)],'d',2);p.line([(16,33),(23,33),(28,35)],'d');p.cluster(35,30,['gmg','.ms','sd.'])
        block(p,14,26,10,9,0);block(p,46,27,9,8,1)
    else:
        p.poly([(16,27),(21,23),(34,23),(41,25),(46,30),(46,39),(41,46),(33,50),(22,48),(15,43),(12,35)],'s',True);p.poly([(17,28),(25,25),(35,26),(40,30),(39,35),(31,38),(21,37),(16,33)],'m');p.poly([(22,27),(27,25),(33,27),(33,30),(27,33),(20,31)],'g');p.poly([(16,38),(24,40),(34,41),(42,37),(42,43),(34,47),(24,45),(19,45)],'d');p.poly([(26,33),(34,31),(39,36),(36,42),(28,44),(23,40)],'m');p.poly([(28,34),(33,33),(36,36),(32,40),(28,39)],'u',True);p.cluster(30,34,['Uh','uC']);p.poly([(13,26),(14,20),(21,19),(24,22),(20,28)],'F',True);p.cluster(16,22,['aau','Fua','.F.']);block(p,46,27,8,9,1)
    fists(p,'stone',34)
    p.part='head';p.pivot=(36,19)
    block(p,35,16,10,10,1)
    p.poly([(29,16),(32,13),(41,14),(46,17),(43,21),(34,21),(29,19)],'s',True);p.line([(31,16),(42,16)],'o',2);p.cluster(34,17,['eE..eE'])
    p.poly([(40,18),(48,19),(49,23),(46,26),(40,25)],'m',True);p.poly([(41,19),(47,20),(46,22),(41,22)],'g');p.cluster(46,22,['ds']);p.line([(32,25),(40,27),(45,26)],'d',2)
    p.poly([(28,10),(33,6),(40,7),(43,10),(38,12),(30,12)],'m' if stone else 'F',True);p.line([(31,9),(36,8),(40,9)],'g' if stone else 'a')
    p.cluster(27,20,['mm','gs','d.']);p.cluster(34,9,['ghm','..g'])
    if pose=='hit':p.line([(33,18),(42,19)],'s',2)
    return p.im

def urn(p):
    pose=p.pose
    if pose=='dead':
        for pts in [[(5,58),(8,49),(16,48),(15,52),(19,60)],[(22,56),(25,47),(35,48),(39,54),(34,60),(26,59)],[(43,57),(48,49),(56,51),(59,59),(54,60)]]:p.poly(pts,'s',True);p.poly([pts[0],pts[1],pts[2]],'m');p.line([pts[1],pts[2]],'g');p.cluster(28,53,['gh','ms']);p.line([(25,54),(31,56),(34,53)],'d')
        return p.im
    for part,x in [('leftleg',23),('rightleg',41)]:
        p.part=part;p.poly([(x-5,50),(x+4,50),(x+5,56),(x+7,58),(x+7,60),(x-6,60),(x-7,57)],'s',True);p.poly([(x-3,52),(x+2,52),(x+2,57),(x-4,57)],'m');p.line([(x-3,58),(x+4,58)],'g')
    p.part='body';s=SWING[pose]
    for side,x,y in [(-1,10-s/3,40-s/2),(1,52+s/3,37-s/2)]:
        if pose=='windup' and side==1:x,y=47,20
        if pose=='attack' and side==1:x,y=53,45
        x=max(8,min(53,x));p.joint([(31+side*11,27),(31+side*17,30),(x,y)],7,'s','g','d')
        p.poly([(x-6,y-7),(x+5,y-7),(x+7,y-2),(x+6,y+6),(x+2,y+8),(x-5,y+6),(x-7,y+1)],'s',True);p.poly([(x-4,y-5),(x+2,y-5),(x+4,y-2),(x+3,y+4),(x-3,y+4)],'m');p.line([(x-4,y-5),(x+3,y-5)],'h');p.line([(x-5,y+3),(x+4,y+3)],'d');p.cluster(x-3,y-1,['gg','gm'])
    p.poly([(23,23),(40,23),(43,29),(48,36),(47,47),(42,53),(23,54),(17,49),(15,41),(17,32)],'s',True);p.poly([(23,26),(35,25),(40,30),(44,37),(42,48),(38,51),(24,50),(19,44),(19,36)],'m');p.poly([(23,29),(27,27),(31,29),(30,35),(27,40),(27,48),(23,47),(20,41),(21,34)],'g');p.line([(24,29),(23,34),(23,40)],'h');p.line([(20,46),(42,46)],'g',2);p.line([(22,51),(40,51)],'d');p.poly([(34,31),(40,33),(42,38),(40,42),(37,41),(36,36)],'s');p.line([(35,29),(37,34),(34,37),(36,42)],'d')
    p.poly([(30,33),(34,31),(38,35),(38,40),(34,43),(30,40)],'B',True);p.line([(32,34),(34,33),(36,36),(35,40),(33,40)],'y');p.cluster(29,46,['mmgg','..gs']);p.cluster(40,41,['gm','sd'])
    p.part='head';p.pivot=(34,19)
    p.poly([(25,9),(40,9),(44,14),(43,24),(38,27),(27,25),(23,20),(23,13)],'s',True);p.poly([(26,12),(35,11),(40,14),(39,21),(34,24),(27,21)],'m');p.poly([(26,13),(31,12),(34,14),(32,17),(26,16)],'g');p.poly([(24,9),(27,6),(38,6),(42,9),(40,12),(35,11),(32,13),(26,12)],'s',True);p.line([(27,8),(37,8)],'h');p.line([(29,9),(31,11),(32,10)],'d')
    p.eye(30,17,p.pose=='hit');p.eye(39,16,p.pose=='hit');p.poly([(35,18),(39,18),(41,21),(38,22),(34,21)],'g');p.cluster(36,19,['hm']);p.line([(29,23),(35,24),(40,23)],'d',2);p.cluster(26,18,['gg','ms'])
    return p.im

def iron(p):
    if p.pose=='dead':
        for j,(x,y,w,h) in enumerate([(10,55,7,5),(24,52,8,8),(43,55,9,5)]):block(p,x,y,w,h,j)
        p.poly([(24,48),(30,45),(39,47),(43,53),(39,57),(31,56),(26,54)],'b',True);p.poly([(29,49),(37,49),(39,53),(35,54)],'R');p.line([(30,50),(36,51)],'p');p.cluster(46,57,['gyg','dsd']);return p.im
    for part,x in [('leftleg',22),('rightleg',42)]:
        p.part=part;p.poly([(x-6,44),(x+5,44),(x+7,50),(x+5,56),(x+9,58),(x+9,60),(x-8,60),(x-8,57),(x-5,53)],'s',True);p.poly([(x-4,46),(x+2,46),(x+3,51),(x+1,55),(x-4,55)],'m');p.line([(x-4,49),(x+3,49)],'g');p.line([(x-5,57),(x+5,57)],'g',2);p.cluster(x+2,51,['dmd','gg.'])
    p.part='body'
    p.poly([(21,23),(40,23),(46,30),(45,40),(39,49),(23,49),(17,43),(16,33)],'s',True);p.poly([(22,26),(31,24),(39,27),(41,34),(37,38),(23,37),(19,33)],'m');p.poly([(24,27),(30,26),(34,29),(32,32),(25,32)],'g');p.poly([(20,37),(42,37),(41,44),(35,48),(24,46)],'d');p.line([(22,39),(37,39)],'m');p.line([(23,45),(36,46)],'g')
    p.poly([(24,30),(36,29),(40,33),(40,40),(35,44),(25,42),(21,36)],'b',True);p.poly([(26,32),(34,31),(37,34),(37,39),(32,41),(26,39),(24,35)],'R');p.poly([(28,33),(32,32),(35,35),(33,38),(28,38)],'p');p.line([(27,34),(32,33)],'q');p.line([(24,34),(37,34)],'b');p.line([(24,37),(37,37)],'b')
    for x,y,w,h in [(14,26,10,8),(47,27,10,9)]:block(p,x,y,w,h);p.line([(x-5,y-4),(x+4,y-3)],'g');p.cluster(x+3,y+1,['yy','Bd'])
    lx,ly,rx,ry=fists(p,'iron',34)
    for x,y in [(lx,ly),(rx,ry)]:p.line([(x-4,y+2),(x+3,y+2)],'b');p.cluster(x-3,y-5,['yg','ds']);p.cluster(x+3,y+4,['yt'])
    p.part='head';p.pivot=(36,20)
    p.poly([(28,10),(33,6),(41,8),(46,13),(45,24),(41,28),(31,27),(27,21)],'s',True);p.poly([(30,12),(35,8),(40,10),(42,15),(38,17),(30,17)],'m');p.line([(33,9),(36,8),(40,10)],'g');p.poly([(29,18),(42,17),(44,21),(40,23),(30,22)],'o');p.cluster(33,19,['eE...eE']);p.poly([(37,21),(43,20),(46,23),(43,26),(38,25)],'m');p.line([(39,22),(44,23)],'g');p.line([(31,24),(36,26),(40,26)],'d');p.line([(34,24),(34,26)],'g');p.line([(37,25),(37,27)],'d')
    p.cluster(28,13,['yt','ds']);p.poly([(28,9),(28,4),(32,4),(34,9)],'d',True);p.line([(28,5),(31,5)],'g');p.cluster(40,11,['gg','ms'])
    return p.im

def crystal(p):
    if p.pose=='dead':
        for j,(x,y,w,h) in enumerate([(10,54,6,4),(24,53,8,5),(40,54,8,4),(53,56,5,2)]):block(p,x,y,w,h,j,True)
        p.poly([(18,51),(15,43),(22,45),(27,52)],'m',True);p.line([(18,46),(21,50)],'h');return p.im
    for part,x in [('leftleg',22),('rightleg',42)]:
        p.part=part;p.poly([(x-5,43),(x+4,43),(x+7,49),(x+3,56),(x+7,59),(x+5,60),(x-7,60),(x-6,55),(x-8,49)],'s',True);p.poly([(x-3,46),(x+2,45),(x+3,50),(x,56),(x-3,54)],'m');p.line([(x-2,47),(x,50),(x-2,55)],'g');p.poly([(x-5,58),(x+2,57),(x+4,59),(x-5,59)],'g')
    p.part='body';p.poly([(21,24),(32,20),(43,25),(47,33),(45,44),(36,50),(24,48),(18,43),(16,34)],'s',True);p.poly([(23,25),(32,22),(40,26),(36,37),(28,46),(20,41)],'m');p.poly([(31,23),(36,26),(34,36),(29,42),(27,32)],'g');p.line([(32,25),(31,33),(29,37)],'h');p.poly([(38,28),(44,32),(42,43),(35,47),(36,39)],'d');p.line([(40,32),(38,42),(35,45)],'m');p.poly([(20,32),(24,27),(26,35),(22,42),(18,39)],'g');p.cluster(24,38,['hg','ms'])
    fists(p,'crystal',33)
    p.poly([(10,32),(7,18),(12,5),(18,13),(20,25),(17,36)],'s',True);p.poly([(12,8),(14,15),(14,27),(11,23),(10,17)],'g');p.line([(12,11),(13,19),(13,24)],'h');p.poly([(48,30),(47,16),(52,10),(56,22),(54,31)],'m',True);p.line([(52,13),(52,24)],'g')
    p.part='head';p.pivot=(35,18);p.poly([(28,10),(33,5),(40,8),(44,15),(44,23),(39,28),(31,25),(26,18)],'s',True);p.poly([(33,7),(38,9),(40,15),(37,18),(30,15)],'m');p.poly([(33,8),(35,11),(34,15),(31,13)],'g');p.line([(30,17),(41,16)],'o',2);p.cluster(34,18,['eE..eE']);p.poly([(38,20),(45,20),(47,24),(42,27),(38,25)],'m');p.poly([(40,21),(43,21),(45,23),(40,24)],'g');p.line([(32,23),(36,26),(40,27)],'d');p.cluster(28,20,['gm','ds'])
    return p.im

def earth(p):
    if p.pose=='dead':
        for j,(x,y,w,h) in enumerate([(10,55,7,5),(28,52,10,8),(49,55,8,5)]):block(p,x,y,w,h,j)
        p.line([(10,56),(19,54),(24,58),(35,57),(43,54)],'F',3);p.line([(20,55),(23,56)],'a');return p.im
    s=SWING[p.pose];p.part='body';block(p,29,39,12,10,1);block(p,11-s/3,35-s/2,7,8,0);block(p,50+s/4,30-s/2,8,7,1)
    p.poly([(18,29),(22,25),(29,26),(37,29),(37,32),(28,31),(22,34),(17,34)],'F',True);p.cluster(22,28,['aaU','uaF','.F.']);p.line([(24,33),(22,38),(25,42),(22,48)],'C',2);p.line([(32,34),(36,39),(32,43),(36,47)],'a');p.cluster(24,43,['gmm','..gs'])
    p.part='tail';block(p,20,54,5,4,0);block(p,41,52,7,5,1);p.line([(19,47),(15,50),(18,53)],'F',3);p.line([(35,47),(39,48),(42,51)],'F',2)
    p.part='body'
    for pts in [[(18,35),(12,29),(10,25)],[(41,34),(48,27),(52,25)]]:p.line(pts,'o',4);p.line(pts,'F',3);p.line([(x-1,y-1) for x,y in pts],'a');x,y=pts[-1];p.poly([(x,y),(x-5,y-4),(x-1,y-6),(x+3,y-3)],'a',True);p.line([(x-2,y-4),(x,y-1)],'U')
    p.part='head';p.pivot=(38,20);block(p,36,18,12,9,1);p.poly([(25,11),(29,6),(37,5),(44,8),(48,13),(42,12),(35,10),(29,13)],'F',True);p.cluster(29,9,['aaUu','FuF.','..F.']);p.line([(30,18),(42,17)],'o',2);p.cluster(34,19,['eE..eE']);p.poly([(39,20),(47,20),(49,24),(46,27),(40,25)],'m',True);p.line([(40,21),(46,21),(47,23)],'g');p.line([(31,24),(37,27),(43,27)],'d',2)
    if p.pose=='attack':p.part='body';p.poly([(52,17),(57,19),(59,25),(55,28),(51,23)],'m',True);p.line([(55,20),(57,24)],'g')
    return p.im
